package com.devai.monitor;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.*;
import java.util.*;
import java.util.regex.*;
@RestController @RequestMapping("/api") @CrossOrigin(origins={"http://localhost:5173","http://127.0.0.1:5173"})
public class AgentController {
 private final AgentExecutionRepository repo;
 private static final Set<String> AGENTS=Set.of("codebase","planner","developer","test","debugger","reviewer");
 public AgentController(AgentExecutionRepository repo){this.repo=repo;}
 @GetMapping("/agents/{agent}/history") public List<AgentExecution> history(@PathVariable String agent){check(agent);return repo.findByAgentOrderByCreatedAtDesc(agent);}
 @PostMapping("/agents/{agent}/execute") public ResponseEntity<?> execute(@PathVariable String agent,@RequestBody Map<String,String> body){check(agent);String input=body.getOrDefault("input","").trim();if(input.isEmpty()||input.length()>30000)return ResponseEntity.badRequest().body(Map.of("error","Input must contain 1–30000 characters."));String out=switch(agent){
 case "codebase"->"CODEBASE INVENTORY (based only on supplied text)\nJava references: "+count(input,"\\.java")+"\nTest references: "+count(input,"Test")+"\nMaven references: "+count(input,"pom.xml")+"\nNext: verify controllers, services, repositories, configurations and dependencies against actual files.";
 case "planner"->"IMPLEMENTATION CHECKLIST\n1. Confirm requirement and acceptance criteria.\n2. Identify affected Java classes and dependencies.\n3. Make smallest isolated change.\n4. Add positive, negative and regression JUnit tests.\n5. Run mvn test in a trusted project or isolated container.\n6. Review diff and request approval.\nInput: "+input.substring(0,Math.min(450,input.length()));
 case "developer"->"IMPLEMENTATION BRIEF (no code was modified)\n1. Create a feature branch.\n2. Locate relevant service/controller/config files.\n3. Implement acceptance criteria from the supplied task.\n4. Add focused JUnit tests.\n5. Check error handling and secrets.\nTask: "+input.substring(0,Math.min(450,input.length()));
 case "test"->"REPRODUCIBLE TEST COMMANDS (NOT EXECUTED)\n./mvnw test  (or mvn test)\n./mvnw verify\nReview target/surefire-reports and failed assertions.\nAdd tests for success, invalid input, permission denied and regression.\nEvidence provided: "+input.substring(0,Math.min(450,input.length()));
 case "debugger"->"DEBUG TRIAGE (heuristic, no fix applied)\n"+(input.toLowerCase().contains("nullpointer")?"Possible null dereference: inspect stack-trace file/line and validate input or initialization.":input.toLowerCase().contains("compilation")||input.contains("cannot find symbol")?"Possible compile failure: inspect imports, dependency versions and symbol spelling.":"Locate first root-cause exception, reproduce with a minimal failing test and inspect recently changed lines.")+"\nRetry limit recommendation: 2; run tests again after each human-approved fix.";
 default->"REVIEW CHECKLIST (not a verified code review)\n[ ] Requirement satisfied\n[ ] Authentication and authorization checked\n[ ] No hard-coded credentials\n[ ] Tests cover failure cases\n[ ] Diff has no unrelated changes\n[ ] Human approval before merge\nSubmitted context: "+input.substring(0,Math.min(450,input.length()));};return ResponseEntity.ok(repo.save(new AgentExecution(agent,input,out)));}
 private void check(String a){if(!AGENTS.contains(a))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND,"Unknown agent");}
 private int count(String s,String p){Matcher m=Pattern.compile(p,Pattern.CASE_INSENSITIVE).matcher(s);int n=0;while(m.find())n++;return n;}
 @PostMapping("/tools/secrets") public ResponseEntity<?> secrets(@RequestBody Map<String,String> body){String s=body.getOrDefault("input","");if(s.isBlank()||s.length()>100000)return ResponseEntity.badRequest().body(Map.of("error","Provide 1–100000 characters."));Map<String,String> patterns=new LinkedHashMap<>();patterns.put("Private key header","-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----");patterns.put("GitHub token","gh[pousr]_[A-Za-z0-9_]{20,}");patterns.put("AWS access key","(?:AKIA|ASIA)[A-Z0-9]{16}");patterns.put("Possible hard-coded secret","(?i)(?:password|api[_-]?key|secret|token)\\s*[:=]\\s*[\\\"']?[^\\s\\\"']{8,}");List<Map<String,Object>> findings=new ArrayList<>();for(var e:patterns.entrySet()){Matcher m=Pattern.compile(e.getValue()).matcher(s);while(m.find()&&findings.size()<30){int line=1;for(int i=0;i<m.start();i++)if(s.charAt(i)=='\n')line++;findings.add(Map.of("type",e.getKey(),"line",line,"match","[REDACTED]"));}}return ResponseEntity.ok(Map.of("findings",findings,"count",findings.size(),"status",findings.isEmpty()?"NO_PATTERN_MATCH":"REVIEW_REQUIRED","note","Pattern screening only; no input persisted. Rotate any real exposed credentials."));}
 @PostMapping("/tools/risk") public ResponseEntity<?> risk(@RequestBody Map<String,String> body){String s=body.getOrDefault("input","").toLowerCase();if(s.isBlank()||s.length()>30000)return ResponseEntity.badRequest().body(Map.of("error","Provide 1–30000 characters."));int score=0;List<String> reasons=new ArrayList<>();String[][] signals={{"auth|jwt|login|permission|security","Authentication or authorization change"},{"migration|schema|database|sql|drop table","Database or schema change"},{"payment|billing|transaction|money","Financial transaction path"},{"production|deployment|docker|infrastructure","Deployment or infrastructure change"},{"delete|remove|breaking|deprecated","Potentially destructive or breaking change"}};for(String[] sig:signals)if(Pattern.compile(sig[0]).matcher(s).find()){score+=20;reasons.add(sig[1]+" (+20)");}if(!Pattern.compile("test|junit|verify|coverage").matcher(s).find()){score+=15;reasons.add("No test evidence mentioned (+15)");}score=Math.min(100,score);return ResponseEntity.ok(Map.of("score",score,"level",score>=60?"HIGH":score>=30?"MEDIUM":"LOW","reasons",reasons,"recommendation",score>=60?"Require senior review and explicit test evidence.":"Validate with focused tests and human review.","note","Transparent keyword heuristic; not a prediction from repository history."));}
}
